function esc(s) { return s; }

function card(t, b) {
  return `        <article class="sds-card">
          <h3 class="sds-h3">${t}</h3>
          <p class="sds-body">${b}</p>
        </article>`;
}

function numCard(i, t, b) {
  return `        <article class="sds-card">
          <p class="ind-num">0${i + 1}</p>
          <h3 class="sds-h3">${t}</h3>
          <p class="sds-body">${b}</p>
        </article>`;
}

function mistake(strong, rest) {
  return `          <li><span class="material-symbols-outlined" aria-hidden="true">close</span><span><strong>${strong}</strong> ${rest}</span></li>`;
}

function faqItem(q, a) {
  return `        <details>
          <summary>${q}</summary>
          <p>${a}</p>
        </details>`;
}

