// Head is lifted from websites.html so every page inherits the full scaffolding
// (theme resolver, critical baseline, tokenised tailwind config with md:880px).
const websites = fs.readFileSync(path.join(ROOT, 'websites.html'), 'utf8').split('\n');
const HEAD = websites.slice(0, 48).join('\n');

function headFor(t) {
  const url = `https://surettesystems.com/web-design-for-${t.slug}.html`;
  let h = HEAD;
  h = h.replace(/<title>[\s\S]*?<\/title>/, `<title>${t.title} | Surette Data Systems</title>`);
  h = h.replace(/(<link rel="canonical" href=")[^"]*(")/, `$1${url}$2`);
  h = h.replace(/(<meta property="og:url" content=")[^"]*(")/, `$1${url}$2`);
  h = h.replace(/(<meta name="description" content=")[^"]*(")/, `$1${t.desc}$2`);
  h = h.replace(/(<meta property="og:description" content=")[^"]*(")/, `$1${t.desc}$2`);
  h = h.replace(/(<meta name="twitter:description" content=")[^"]*(")/, `$1${t.desc}$2`);
  h = h.replace(/(<meta property="og:title" content=")[^"]*(")/, `$1${t.title}$2`);
  h = h.replace(/(<meta name="twitter:title" content=")[^"]*(")/, `$1${t.title}$2`);
  return h;
}

let n = 0;
for (const t of TRADES) {
  const file = path.join(ROOT, `web-design-for-${t.slug}.html`);
  fs.writeFileSync(file, headFor(t) + buildBody(t), 'utf8');
  n++;
  console.log('  wrote web-design-for-' + t.slug + '.html');
}

